# Idempotency keys: unique key + request hash + stored response
import hashlib, json
store = {}          # key -> {"hash":..., "status":..., "response":...}
balance = {"acct": 100}

def pay(key, amount):
    h = hashlib.sha256(json.dumps(amount).encode()).hexdigest()[:8]
    rec = store.get(key)
    if rec:
        if rec["hash"] != h:
            return "422 key reused with different request"
        if rec["status"] == "STARTED":
            return "409 in flight, retry later"
        return "200 replay: " + rec["response"]       # same answer again
    store[key] = {"hash": h, "status": "STARTED", "response": ""}
    balance["acct"] -= amount                          # the real effect, once
    resp = "charged %d, balance %d" % (amount, balance["acct"])
    store[key].update(status="COMPLETED", response=resp)
    return "200 " + resp

print(pay("k1", 30))
print(pay("k1", 30))       # client retry after timeout
print(pay("k1", 50))       # misuse of same key
print(pay("k2", 20))
print("final balance:", balance["acct"])
